-- Little Treat Menu & HPP / source: recipes.js SOP baseline 11 Nov 2026
-- Dedicated Supabase project ONLY. Safe to re-run; all items stay inactive.
-- 30 design identities: 16 coffees × four sizes, 9 banana recipes, 5 dimsum.
-- Blank material prices: NEVER invent suppliers, COGS, or selling prices.
-- Alias/unit normalization (rechecked in repository tests):
--   buah/lembar -> pcs; air temperature/process -> Air bersih;
--   nori/chili oil/pisang spelling harmonized across recipe sources.
-- Assumed packaging included to avoid invisible packaging costs:
--   coffee = one sized cup, one lid/seal, one straw;
--   banana = one box per order, sauce cups where recipe pack says so.
-- These packaging assumptions REQUIRE physical operational sign-off.
-- Frying oil depletion, electricity, gas, wastage and labor are NOT in raw BOM.
-- Internally prepared premix/sauces cost depends on *real batch yield*;
-- no automatic inferred prices from S01-S08.

create table if not exists public.lt_material_quotes (
  material_id uuid primary key references public.lt_materials(id) on delete cascade,
  supplier text not null check(length(btrim(supplier)) between 2 and 140),
  pack_cost numeric(14,2) not null check(pack_cost>0 and pack_cost<=999999999999.99),
  pack_qty numeric(14,3) not null check(pack_qty>0),
  cost_per_unit numeric(14,4) generated always as (round(pack_cost/pack_qty,4)) stored,
  quote_on date not null default ((now() at time zone 'Asia/Jakarta')::date),
  source_note text not null default '' check(length(source_note)<=300),
  updated_by uuid not null references auth.users(id),
  updated_at timestamptz not null default now()
);
alter table public.lt_material_quotes enable row level security;
revoke all on public.lt_material_quotes from public,anon,authenticated;
grant select,insert on public.lt_material_quotes to authenticated;
grant update(supplier,pack_cost,pack_qty,quote_on,source_note,updated_by,updated_at)
 on public.lt_material_quotes to authenticated;
create policy lt_material_quotes_owner on public.lt_material_quotes for all to authenticated
 using(exists(select 1 from public.lt_members m where m.user_id=(select auth.uid()) and m.active and m.role='owner'))
 with check(exists(select 1 from public.lt_members m where m.user_id=(select auth.uid()) and m.active and m.role='owner'));

do $seed$
declare
 v_row jsonb;v_material jsonb;v_product uuid;v_material_id uuid;
begin
 for v_row in select value from pg_catalog.jsonb_array_elements($catalog$
