ung roti panko","unit":"g","qty":35},{"name":"Dark Choco Dip","unit":"g","qty":20},{"name":"Salted Palm Caramel","unit":"g","qty":20},{"name":"Cup saus","unit":"pcs","qty":4},{"name":"Box pisang bersekat","unit":"pcs","qty":1}]},{"sku":"D01","recipe_key":"D01","category":"dimsum","name":"Classic Chicken Dimsum","ingredients":[{"name":"Dimsum ayam frozen","unit":"pcs","qty":4},{"name":"Saus merah komersial","unit":"g","qty":15},{"name":"Box kecil","unit":"pcs","qty":1},{"name":"Cup saus","unit":"pcs","qty":1}]},{"sku":"D02","recipe_key":"D02","category":"dimsum","name":"Hot Chili Oil Dimsum","ingredients":[{"name":"Dimsum ayam frozen","unit":"pcs","qty":4},{"name":"Chili oil komersial","unit":"g","qty":12},{"name":"Box kecil","unit":"pcs","qty":1},{"name":"Cup saus","unit":"pcs","qty":1}]},{"sku":"D03","recipe_key":"D03","category":"dimsum","name":"Creamy Mentai-Style","ingredients":[{"name":"Dimsum ayam frozen","unit":"pcs","qty":4},{"name":"Creamy Mentai-Style","unit":"g","qty":30},{"name":"Nori bubuk","unit":"g","qty":0.3},{"name":"Box kecil","unit":"pcs","qty":1}]},{"sku":"D04","recipe_key":"D04","category":"dimsum","name":"Duo Mood Dimsum","ingredients":[{"name":"Dimsum ayam frozen","unit":"pcs","qty":6},{"name":"Creamy Mentai-Style","unit":"g","qty":22},{"name":"Chili oil komersial","unit":"g","qty":10},{"name":"Nori bubuk","unit":"g","qty":0.3},{"name":"Box bersekat","unit":"pcs","qty":1},{"name":"Cup saus","unit":"pcs","qty":1}]},{"sku":"D05","recipe_key":"D05","category":"dimsum","name":"Dimsum Sharing Box","ingredients":[{"name":"Dimsum ayam frozen","unit":"pcs","qty":10},{"name":"Creamy Mentai-Style","unit":"g","qty":35},{"name":"Chili oil komersial","unit":"g","qty":20},{"name":"Nori bubuk","unit":"g","qty":0.5},{"name":"Box besar","unit":"pcs","qty":1},{"name":"Cup saus","unit":"pcs","qty":2}]}]
$catalog$::jsonb) loop
  insert into public.lt_products(sku,name,category,recipe_key,price,active)
    values(v_row->>'sku',v_row->>'name',v_row->>'category',v_row->>'recipe_key',0,false)
    on conflict(sku) do nothing;
  select id into v_product from public.lt_products where sku=v_row->>'sku';
  if v_product is null then raise exception 'Unknown product %',v_row->>'sku';end if;
  -- Existing operator-edited BOM is never overwritten by a seed migration.
  if exists(select 1 from public.lt_bom where product_id=v_product) then continue;end if;
  for v_material in select value from pg_catalog.jsonb_array_elements(v_row->'ingredients') loop
    insert into public.lt_materials(name,unit)
    values(v_material->>'name',v_material->>'unit')
    on conflict(name) do nothing;
    select id into v_material_id from public.lt_materials
      where name=v_material->>'name' and unit=v_material->>'unit';
    if v_material_id is null then
      raise exception 'Material unit conflict: %',v_material->>'name';
    end if;
    insert into public.lt_bom(product_id,material_id,qty_per_unit)
    values(v_product,v_material_id,(v_material->>'qty')::numeric)
    on conflict(product_id,material_id) do nothing;
  end loop;
 end loop;
end $seed$;

-- Database-level safety: client-side validity checks are not a security boundary.
create or replace function public.lt_validate_menu_activation()
 returns trigger language plpgsql security invoker set search_path='' as $fn$
declare v_missing int;
begin
 if not new.active then return new; end if;
 if new.category='coffee' and new.sku ~ '^K[0-9]{2}$'
   then raise exception 'Use a 12/14/16/22 oz SKU, not the unsized coffee template'; end if;
 if new.price<=0 then raise exception 'Masukkan harga jual sebelum aktif';end if;
 select count(*) into v_missing from public.lt_bom b
 left join public.lt_material_costs c on c.material_id=b.material_id
 where b.product_id=new.id and (c.material_id is null or c.avg_cost_per_unit<=0);
 if not exists(select 1 from public.lt_bom where product_id=new.id) or v_missing>0
   then raise exception 'HPP riil belum lengkap: isi biaya melalui penerimaan pembelian untuk semua bahan BOM'; end if;
 if new.category='coffee' and not exists(
   select 1 from public.lt_bom b join public.lt_materials m on m.id=b.material_id
   where b.product_id=new.id and m.name like 'Cup % oz'
 ) then raise exception 'Kemasan cup belum masuk BOM';end if;
 if new.category='banana' and not exists(
   select 1 from public.lt_bom b join public.lt_materials m on m.id=b.material_id
   where b.product_id=new.id and m.name like 'Box pisang%'
 ) then raise exception 'Kemasan box belum masuk BOM';end if;
 if new.category='dimsum' and not exists(
   select 1 from public.lt_bom b join public.lt_materials m on m.id=b.material_id
   where b.product_id=new.id and m.name like 'Box %'
 ) then raise exception 'Kemasan dimsum belum masuk BOM';end if;
 return new;
end $fn$;
revoke all on function public.lt_validate_menu_activation() from public,anon,authenticated;
drop trigger if exists lt_product_activation_guard on public.lt_products;
create trigger lt_product_activation_guard
  before insert or update of active,price on public.lt_products
  for each row execute function public.lt_validate_menu_activation();

-- Owner must set inactive before modifying BOM. Prevents silent cost drift while sold.
create or replace function public.lt_guard_active_bom()
 returns trigger language plpgsql security invoker set search_path='' as $fn$
declare v_product uuid;v_active boolean;
begin
 v_product:=case when TG_OP='DELETE' then old.product_id else new.product_id end;
 select active into v_active from public.lt_products where id=v_product;
 if v_active then raise exception 'Nonaktifkan menu sebelum mengubah komposisi BOM';end if;
 return case when TG_OP='DELETE' then old else new end;
end $fn$;
revoke all on function public.lt_guard_active_bom() from public,anon,authenticated;
drop trigger if exists lt_bom_active_guard on public.lt_bom;
create trigger lt_bom_active_guard before insert or update or delete on public.lt_bom
  for each row execute function public.lt_guard_active_bom();
